#include "semantic/semantic.h"
#include "symbol_table/symbol_table.h"
#include <iostream>
static int errors=0; static SymbolTable symbols;
static Type expr(Node*n){if(!n)return Type::Error;if(n->kind=="literal"){if(n->text=="true"||n->text=="false")return Type::Bool;return n->text.find('.')==std::string::npos?Type::Int:Type::Float;}if(n->kind=="id"){auto t=symbols.lookup(n->text);if(t==Type::Error){std::cerr<<"line "<<n->line<<": undeclared variable '"<<n->text<<"'\n";++errors;}return t;}if(n->kind=="unary"){auto t=expr(n->children[0]);if(n->text=="!"&&t!=Type::Bool){std::cerr<<"line "<<n->line<<": ! requires boolean\n";++errors;return Type::Error;}return n->text=="!"?Type::Bool:t;}if(n->kind=="binary"){auto a=expr(n->children[0]),b=expr(n->children[1]);if(a==Type::Error||b==Type::Error)return Type::Error;bool cmp=n->text=="<"||n->text==">"||n->text=="<="||n->text==">="||n->text=="=="||n->text=="!=";bool logic=n->text=="&&"||n->text=="||";if(logic){if(a!=Type::Bool||b!=Type::Bool)goto bad;return Type::Bool;}if(cmp){if(a==Type::Bool||b==Type::Bool){if(a!=b||!(n->text=="=="||n->text=="!="))goto bad;}return Type::Bool;}if(a==Type::Bool||b==Type::Bool)goto bad;return a==Type::Float||b==Type::Float?Type::Float:Type::Int;bad:std::cerr<<"line "<<n->line<<": incompatible operands for '"<<n->text<<"'\n";++errors;return Type::Error;}return Type::Error;}
static void stmt(Node*n){if(!n)return;if(n->kind=="block"){symbols.enter();for(auto*c:n->children)stmt(c);symbols.leave();return;}if(n->kind=="decl"){Type t=n->text=="int"?Type::Int:n->text=="float"?Type::Float:Type::Bool;if(!symbols.declare(n->children[0]->text,t)){std::cerr<<"line "<<n->line<<": redeclaration of '"<<n->children[0]->text<<"'\n";++errors;}if(n->children.size()>1&&expr(n->children[1])!=t){std::cerr<<"line "<<n->line<<": initializer type mismatch\n";++errors;}return;}if(n->kind=="assign"){auto t=symbols.lookup(n->text);if(t==Type::Error){std::cerr<<"line "<<n->line<<": undeclared variable '"<<n->text<<"'\n";++errors;}else if(expr(n->children[0])!=t) {std::cerr<<"line "<<n->line<<": assignment type mismatch\n";++errors;}return;}if(n->kind=="if"||n->kind=="while"){if(expr(n->children[0])!=Type::Bool){std::cerr<<"line "<<n->line<<": condition must be boolean\n";++errors;}stmt(n->children[1]);if(n->children.size()>2)stmt(n->children[2]);return;}if(n->kind=="print"){expr(n->children[0]);return;}for(auto*c:n->children)stmt(c);}
bool analyze(Node*r){errors=0;symbols=SymbolTable{};if(r)for(auto*c:r->children)stmt(c);return errors==0;}
